import { createHash } from 'node:crypto';
import { mkdir, readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';
import sharp from 'sharp';
import { brandingSchema, type Branding } from '#config/branding-schema.ts';

export type GeneratedFile = {
	path: string;
	contents: Buffer | string;
};

export const GENERATED_HEADER =
	'// Generated by scripts/generate.ts from config/branding.json. Do not edit.\n';

const ICON_ROLES = [
	{ role: 'favicon', slug: 'favicon', sizeKey: 'favicon' },
	{ role: 'appleTouch', slug: 'apple-touch', sizeKey: 'appleTouch' },
	{ role: 'icon192', slug: 'icon-192', sizeKey: 'icon192' },
	{ role: 'icon512', slug: 'icon-512', sizeKey: 'icon512' },
	{ role: 'maskable', slug: 'maskable-512', sizeKey: 'maskable' }
] as const;

type IconRole = (typeof ICON_ROLES)[number]['role'];

function sha256(contents: Buffer | string): string {
	return createHash('sha256').update(contents).digest('hex');
}

async function renderIcon(
	svg: Buffer,
	branding: Branding,
	size: number,
	maskable: boolean
): Promise<Buffer> {
	if (maskable) {
		const innerSize = Math.round(size * branding.maskableScale);
		const inner = await sharp(svg).resize(innerSize, innerSize).png().toBuffer();
		return sharp({
			create: {
				width: size,
				height: size,
				channels: 4,
				background: branding.themeColor
			}
		})
			.composite([{ input: inner, gravity: 'center' }])
			.png({ compressionLevel: 9 })
			.toBuffer();
	}

	return sharp(svg)
		.resize(size, size)
		.flatten({ background: branding.themeColor })
		.png({ compressionLevel: 9 })
		.toBuffer();
}

function buildManifest(branding: Branding, icons: Record<IconRole, string>) {
	return `${JSON.stringify(
		{
			id: branding.startUrl,
			name: branding.name,
			short_name: branding.shortName,
			description: branding.description,
			lang: branding.locale,
			dir: 'ltr',
			start_url: branding.startUrl,
			scope: branding.scope,
			display: branding.display,
			background_color: branding.backgroundColor,
			theme_color: branding.themeColor,
			categories: branding.categories,
			icons: [
				{
					src: icons.icon192,
					sizes: '192x192',
					type: 'image/png',
					purpose: 'any'
				},
				{
					src: icons.icon512,
					sizes: '512x512',
					type: 'image/png',
					purpose: 'any'
				},
				{
					src: icons.maskable,
					sizes: '512x512',
					type: 'image/png',
					purpose: 'maskable'
				}
			]
		},
		null,
		2
	)}\n`;
}

function buildBrandingModule(
	branding: Branding,
	icons: Record<IconRole, string>
) {
	const value = {
		name: branding.name,
		shortName: branding.shortName,
		description: branding.description,
		locale: branding.locale,
		timezone: branding.timezone,
		startUrl: branding.startUrl,
		scope: branding.scope,
		display: branding.display,
		themeColor: branding.themeColor,
		backgroundColor: branding.backgroundColor,
		manifestPath: '/manifest.webmanifest',
		icons
	};

	return `${GENERATED_HEADER}export const branding = ${JSON.stringify(
		value,
		null,
		2
	)} as const;\n\nexport type Branding = typeof branding;\n`;
}

export async function generateBranding(root: string): Promise<GeneratedFile[]> {
	const raw = JSON.parse(
		await readFile(path.join(root, 'config/branding.json'), 'utf8')
	);
	const branding = brandingSchema.parse(raw);
	const svg = await readFile(path.join(root, branding.iconSource));

	const icons = {} as Record<IconRole, string>;
	const files: GeneratedFile[] = [];

	for (const { role, slug, sizeKey } of ICON_ROLES) {
		const size = branding.icons[sizeKey];
		const contents = await renderIcon(svg, branding, size, role === 'maskable');
		const digest = sha256(contents).slice(0, 12);
		const publicPath = `/icons/${slug}-${size}.${digest}.png`;
		icons[role] = publicPath;
		files.push({ path: `static${publicPath}`, contents });
	}

	const manifest = buildManifest(branding, icons);
	files.push({ path: 'static/manifest.webmanifest', contents: manifest });

	const moduleSource = buildBrandingModule(branding, icons);
	files.push({ path: 'src/lib/generated/branding.ts', contents: moduleSource });

	const checksums = {
		generatedBy: 'scripts/generate.ts',
		source: 'config/branding.json',
		files: Object.fromEntries(
			files.map((file) => [file.path, sha256(file.contents)])
		)
	};
	files.push({
		path: 'static/generated-assets.json',
		contents: `${JSON.stringify(checksums, null, 2)}\n`
	});

	return files;
}

export async function writeGeneratedFiles(
	root: string,
	files: GeneratedFile[]
): Promise<void> {
	for (const file of files) {
		const target = path.join(root, file.path);
		await mkdir(path.dirname(target), { recursive: true });
		await writeFile(target, file.contents);
	}
}

export function checksumOf(contents: Buffer | string): string {
	return sha256(contents);
}
